my_tests = [('1\n',1), ('2\n',2), ('4\n',4), ('9\n', 9), ('3\n', 3), ('8\n',8), ('18\n',18), ('25\n',25), ('204\n',204), ('511\n', 511), ('1234\n',1234), ('1450\n', 1450), ('1453\n', 1453), ('1454\n',1454)]

def generate():
    return my_tests

def is_square (l: list, order: int):
    if len(l) != order:
        return False
    for raw in l:
        if len(raw) != order:
            return False
    return True

def are_nums_different(l: list, order):
    s = set()
    for raw in l:
        for el in raw:
            s.add(el)
    return len(s) == order*order

def sum_column(l: list, ind: int):
    sum = 0
    for col_ind in range(len(l)):
        sum += l[col_ind][ind]
    return sum

def check_magic_square(s, order):
    #fastly check order 2
    if order == 2:
        if s == 'NO':
            return True
        else:
            return False

    #convert ouput to 2d array, if possible
    try:
        l = [[int(i) for i in str.strip().split()] for str in s.splitlines()]
    except Exception:
        return False

    #check if output is square and has the size we need
    if not is_square(l, order) or not are_nums_different(l, order):
        return False

    #check the square itself
    sz = len(l)
    expected_sum = sum([l[i][i] for i in range(sz)])

    if sum([l[i][sz-i-1] for i in range(sz)]) != expected_sum:
       return False

    for raw in l:
        if sum(raw) != expected_sum:
            return False

    for column_index in range(len(l)):
        if(sum_column(l, column_index)) != expected_sum:
            return False

    #checked all invalid states
    return True

def check(reply, clue):
    return check_magic_square(reply.strip(), int(clue))
